const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('booking-confirmation');
const count = document.getElementById('booking-count');

function localDateString(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

dateInput.min = localDateString();

function formatDate(value) {
  const date = new Date(`${value}T00:00:00`);
  return date.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
}

function updateCount() {
  count.textContent = list.querySelectorAll('[data-testid="booking"][data-status="active"]').length;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.checkValidity()) {
    form.reportValidity();
    return;
  }
  const data = new FormData(form);
  if (data.get('date') < localDateString()) {
    dateInput.setCustomValidity('Please choose today or a future date.');
    dateInput.reportValidity();
    dateInput.setCustomValidity('');
    return;
  }
  emptyState.hidden = true;
  const booking = document.createElement('article');
  booking.className = 'booking';
  booking.dataset.testid = 'booking';
  booking.dataset.status = 'active';
  const top = document.createElement('div');
  top.className = 'booking-top';
  const details = document.createElement('div');
  const name = document.createElement('p');
  name.className = 'booking-name';
  name.dataset.testid = 'booking-name-display';
  name.textContent = data.get('name');
  const type = document.createElement('div');
  type.className = 'booking-type';
  type.textContent = data.get('type');
  details.append(name, type);
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'cancel-button';
  cancel.dataset.testid = 'booking-cancel';
  cancel.textContent = 'Cancel';
  top.append(details, cancel);
  const info = document.createElement('div');
  info.className = 'booking-info';
  info.textContent = `${formatDate(data.get('date'))} · ${data.get('time')} · ${data.get('email')}`;
  booking.append(top, info);
  list.prepend(booking);
  cancel.addEventListener('click', () => {
    booking.dataset.status = 'cancelled';
    cancel.remove();
    const label = document.createElement('span');
    label.className = 'cancelled-label';
    label.textContent = 'Cancelled';
    top.appendChild(label);
    updateCount();
  });
  updateCount();
  confirmation.textContent = `Appointment created for ${data.get('name')}.`;
  confirmation.hidden = false;
  form.reset();
  dateInput.min = localDateString();
  setTimeout(() => { confirmation.hidden = true; }, 5000);
});

